WITH scored AS (SELECT id, dept_name, location, budget, AVG(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS budget_avg_3, SUM(budget) OVER w_ordered AS running_budget, ROUND(budget / SUM(budget) OVER (PARTITION BY dept_name, location), 4) AS budget_share FROM departments WINDOW w_ordered AS (ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT dept_name, COUNT(CASE WHEN location = 'Tokyo' THEN 1 END) AS tokyo_count, COUNT(*) FILTER (WHERE location = 'Tokyo') AS tokyo_rows, COUNT_IF(dept_name = 'HR') AS hr_events FROM scored GROUP BY 1
